```rust
fn main() {
    let numbers = vec![1, 2, 3, 4, 5];

    // Transforme chaque élément en son double
    let doubled_numbers = numbers.iter().map(|&x| x * 2).collect::<Vec<i32>>();

    // Filtre les nombres qui sont plus grands que 3
    let filtered_numbers = numbers.iter().filter(|&x| x > 3).collect::<Vec<i32>>();

