    let all_numbers = doubled_numbers.iter().chain(filtered_numbers.iter()).cloned().collect::<Vec<i32>>();

    println!("Doublés: {:?}", doubled_numbers);
    println!("Filtres: {:?}", filtered_numbers);
    println!("Tous: {:?}", all_numbers);
}
```

## Explication
